 void handshake(){phase=1;rx.clear();QByteArray b="DORIC\n";b+=hex("1b81060220142176358c1ef069ced27be3c1d796929737dbb56b479a29fcea1be6200bccfb202b2f251870aabde90fb7bd0427fe762feba01c4f41dbb48aa6c3e2af3259211002204d5a6de53873433a3088fb770e5651f0b5a5eca3cf7f0845f8d8061fc0382905209bab1c04b4bb64fd14210e47561c87ca88d251ede373fe956452e729e314092c");tx(b);}
