public:
 Panel(){auto *v=new QVBoxLayout(this);v->addWidget(new QLabel("<b>Sab Sound | Cisco PTZ</b>"));ip=new QLineEdit(settings.value("ip","192.168.0.224").toString());v->addWidget(ip);trust=new QCheckBox("Accept certificat camera neverificat (LAN privat)");v->addWidget(trust);auto *r=new QHBoxLayout;auto *c=new QPushButton("Conectare"),*d=new QPushButton("Deconectare");r->addWidget(c);r->addWidget(d);v->addLayout(r);status=new QLabel;v->addWidget(status);controls=new QWidget;v->addWidget(controls);auto *cv=new QVBoxLayout(controls);speed=new QSpinBox;speed->setRange(1,5);speed->setValue(1);cv->addWidget(new QLabel("Viteza PTZ"));cv->addWidget(speed);auto *g=new QGridLayout;cv->addLayout(g);const char *labels[]={"NW","Sus","NE","Stanga","CENTRU","Dreapta","SW","Jos","SE"};int ops[]={0x1b,0x19,0x1c,0x17,0,0x18,0x1d,0x1a,0x1e};for(int i=0;i<9;i++){auto *b=new QPushButton(labels[i]);b->setStyleSheet(i==4?"QPushButton{background-color:#176b70;color:white;border:1px solid #218a90;border-radius:4px;padding:5px;}QPushButton:hover{background-color:#218a90;}QPushButton:pressed{background-color:#243447;}QPushButton:disabled{background-color:#34383e;color:#888;border-color:#444;}":"QPushButton{background-color:#294c70;color:white;border:1px solid #38658f;border-radius:4px;padding:5px;}QPushButton:hover{background-color:#38658f;}QPushButton:pressed{background-color:#243447;}QPushButton:disabled{background-color:#34383e;color:#888;border-color:#444;}");g->addWidget(b,i/3,i%3);if(i==4)connect(b,&QPushButton::clicked,this,[this]{cmd("0C01011300010001A020010000");});else motion(b,ops[i],i%2==0);}auto *z=new QGridLayout;cv->addLayout(z);const char *ml[]={"Zoom -","Zoom +","Focus Near","Focus Far"};int mo[]={0x22,0x21,0x25,0x26};for(int i=0;i<4;i++){auto *b=new QPushButton(ml[i]);if(i<2)b->setStyleSheet("QPushButton{background-color:#176b70;color:white;border:1px solid #218a90;border-radius:4px;padding:5px;}QPushButton:hover{background-color:#218a90;}QPushButton:pressed{background-color:#243447;}QPushButton:disabled{background-color:#34383e;color:#888;border-color:#444;}");z->addWidget(b,i/2,i%2);motion(b,mo[i]);}for(int i=1;i<=4;++i){auto key=QString("position/%1/").arg(i);auto *pg=new QGroupBox(QString("Position %1").arg(i));auto *pf=new QFormLayout(pg);auto *pp=new QSpinBox(pg),*pt=new QSpinBox(pg),*pz=new QSpinBox(pg);pp->setRange(-1500,1500);pt->setRange(-500,500);pz->setRange(6000,8000);pp->setValue(settings.value(key+"pan",0).toInt());pt->setValue(settings.value(key+"tilt",0).toInt());pz->setValue(settings.value(key+"zoom",8000).toInt());pf->addRow("Pan",pp);pf->addRow("Tilt",pt);pf->addRow("Zoom",pz);auto *ps=new QPushButton(QString("Position Set %1").arg(i),pg);ps->setStyleSheet("QPushButton{background-color:#294c70;color:white;border:1px solid #38658f;border-radius:4px;padding:5px;}QPushButton:hover{background-color:#38658f;}QPushButton:pressed{background-color:#243447;}QPushButton:disabled{background-color:#34383e;color:#888;border-color:#444;}");pf->addRow(ps);connect(pp,qOverload<int>(&QSpinBox::valueChanged),this,[this,key](int v){settings.setValue(key+"pan",v);});connect(pt,qOverload<int>(&QSpinBox::valueChanged),this,[this,key](int v){settings.setValue(key+"tilt",v);});connect(pz,qOverload<int>(&QSpinBox::valueChanged),this,[this,key](int v){settings.setValue(key+"zoom",v);});connect(ps,&QPushButton::clicked,this,[this,pp,pt,pz]{position(pp->value(),pt->value(),pz->value());});cv->addWidget(pg);}auto *actions=new QGridLayout;cv->addLayout(actions);const char *names[]={"Power ON","Power OFF","LED verde ON","LED verde OFF","Autofocus (test)"};const char *packets[]={"0301012b","0301012c","0401010c00","0401010c01","03010129"};for(int i=0;i<5;i++){auto *b=new QPushButton(names[i]);if(i==0||i==2)b->setStyleSheet("QPushButton{background-color:#286443;color:white;border:1px solid #388257;border-radius:4px;padding:5px;}QPushButton:hover{background-color:#388257;}QPushButton:pressed{background-color:#243447;}QPushButton:disabled{background-color:#34383e;color:#888;border-color:#444;}");else if(i==1||i==3)b->setStyleSheet("QPushButton{background-color:#783c42;color:white;border:1px solid #984d55;border-radius:4px;padding:5px;}QPushButton:hover{background-color:#984d55;}QPushButton:pressed{background-color:#243447;}QPushButton:disabled{background-color:#34383e;color:#888;border-color:#444;}");actions->addWidget(b,i/2,i%2);const char *p=packets[i];connect(b,&QPushButton::clicked,this,[this,p]{cmd(p);});}raw=new QLineEdit;raw->setPlaceholderText("HEX DORIC");cv->addWidget(raw);auto *send=new QPushButton("Trimite HEX experimental");cv->addWidget(send);connect(send,&QPushButton::clicked,this,[this]{QString s=raw->text();s.remove(QRegularExpression("[\\s-]"));if(s.isEmpty()||s.size()%2||s.size()>256||s.contains(QRegularExpression("[^0-9a-fA-F]")))return;auto p=QByteArray::fromHex(s.toLatin1());if(p.size()<4||static_cast<unsigned char>(p[0])!=p.size()-1){note("Lungime HEX invalida");return;}if(QMessageBox::question(this,"HEX experimental","Trimit o singura data? Poate modifica starea camerei.")==QMessageBox::Yes){halt();tx(p);}});log=new QPlainTextEdit;log->setReadOnly(true);log->setMaximumBlockCount(1500);v->addWidget(log);auto *save=new QPushButton("Salveaza jurnal");v->addWidget(save);connect(save,&QPushButton::clicked,this,[this]{auto path=QFileDialog::getSaveFileName(this,"Jurnal","DORIC.txt");QFile f(path);if(f.open(QIODevice::WriteOnly))f.write(log->toPlainText().toUtf8());});guard.setSingleShot(false);connect(&guard,&QTimer::timeout,this,[this]{if(moving&&phase==3)tx(motionPacket);else guard.stop();});handshakeTimer.setSingleShot(true);connect(&handshakeTimer,&QTimer::timeout,this,[this]{note("Timeout conectare");sock.abort();});connect(c,&QPushButton::clicked,this,[this]{if(!trust->isChecked()){note("Confirma certificatul neverificat pentru camera din LAN.");return;}halt();sock.abort();phase=0;ready(false);note(QString("Qt runtime: %1").arg(qVersion()));note("Qt plugin paths: "+QCoreApplication::libraryPaths().join("; "));note("TLS backends: "+QSslSocket::availableBackends().join(", "));if(!QSslSocket::supportsSsl()){note("TLS indisponibil: backend Qt lipsa sau incompatibil.");return;}note("TLS backend: "+QSslSocket::activeBackend());settings.setValue("ip",ip->text().trimmed());auto cfg=sock.sslConfiguration();cfg.setProtocol(QSsl::TlsV1_0OrLater);cfg.setPeerVerifyMode(QSslSocket::VerifyNone);sock.setSslConfiguration(cfg);handshakeTimer.start(8000);sock.connectToHostEncrypted(ip->text().trimmed(),13496);});connect(d,&QPushButton::clicked,this,[this]{halt();sock.disconnectFromHost();});connect(&sock,&QSslSocket::encrypted,this,[this]{handshake();});connect(&sock,&QSslSocket::readyRead,this,[this]{receive();});connect(&sock,&QSslSocket::disconnected,this,[this]{phase=0;moving=false;guard.stop();handshakeTimer.stop();ready(false);});connect(&sock,&QSslSocket::errorOccurred,this,[this](auto){note(sock.errorString());guard.stop();moving=false;handshakeTimer.stop();phase=0;ready(false);});connect(qApp,&QGuiApplication::applicationStateChanged,this,[this](Qt::ApplicationState state){if(state!=Qt::ApplicationActive)halt();});ready(false);}
