static Panel *panel=nullptr;
bool obs_module_load(){panel=new Panel; if(!obs_frontend_add_dock_by_id("sabsound-cisco-ptz","Sab Sound Cisco PTZ",panel)){delete panel;panel=nullptr;return false;}return true;}
void obs_module_unload(){if(panel){obs_frontend_remove_dock("sabsound-cisco-ptz");panel=nullptr;}}
